export type Source = 'Pi' | 'Claude'
export type EntryKind = 'directory' | 'file'
export type Entry = { source: Source; path: string; kind: EntryKind }

export const sources: ReadonlyArray<{ source: Source; slug: string }> = [
  { source: 'Pi', slug: 'pi' },
  { source: 'Claude', slug: 'claude' },
]

export type Location =
  | { kind: 'home' }
  | { kind: 'folder'; source: Source; segments: string[] }
  | { kind: 'unknown'; slug: string }

export const homeHref = '/'

/** Builds a folder URL, encoding every segment so spaces, '#', '?', '%' and '/'-free names round-trip. */
export function folderHref(source: Source, segments: string[]): string {
  const slug = sources.find(entry => entry.source === source)!.slug
  return '/' + [slug, ...segments].map(encodeURIComponent).join('/')
}

/** Parses a pathname back into a location. Malformed encodings or unknown sources become 'unknown'. */
export function parsePathname(pathname: string): Location {
  const raw = pathname.split('/').filter(segment => segment !== '')
  if (raw.length === 0) return { kind: 'home' }
  let segments: string[]
  try {
    segments = raw.map(decodeURIComponent)
  } catch {
    return { kind: 'unknown', slug: raw[0] }
  }
  const [slug, ...rest] = segments
  const match = sources.find(entry => entry.slug === slug.toLowerCase())
  if (!match) return { kind: 'unknown', slug }
  return { kind: 'folder', source: match.source, segments: rest }
}

const collator = new Intl.Collator('en', { numeric: true, sensitivity: 'base' })
export function compareNames(a: string, b: string): number {
  return collator.compare(a, b) || (a < b ? -1 : a > b ? 1 : 0)
}

export function entryName(entry: Entry): string {
  const index = entry.path.lastIndexOf('/')
  return index === -1 ? entry.path : entry.path.slice(index + 1)
}

export function entrySegments(entry: Entry): string[] {
  return entry.path.split('/')
}

/** Folders first, then Markdown files; alphabetical (case-insensitive, numeric-aware) within each group. */
export function sortChildren(children: Entry[]): Entry[] {
  return [...children].sort((a, b) => {
    if (a.kind !== b.kind) return a.kind === 'directory' ? -1 : 1
    return compareNames(entryName(a), entryName(b))
  })
}

function key(source: Source, path: string): string {
  return `${source}\u0000${path}`
}

/** Immediate children of every directory (source roots have path ''), built once from the flat API response. */
export type Tree = { children: Map<string, Entry[]> }

export function buildTree(entries: Entry[]): Tree {
  const children = new Map<string, Entry[]>()
  for (const { source } of sources) children.set(key(source, ''), [])
  for (const entry of entries) {
    if (entry.kind === 'directory') children.set(key(entry.source, entry.path), [])
  }
  for (const entry of entries) {
    const index = entry.path.lastIndexOf('/')
    const parent = index === -1 ? '' : entry.path.slice(0, index)
    const siblings = children.get(key(entry.source, parent))
    if (siblings) siblings.push(entry)
  }
  for (const [id, list] of children) children.set(id, sortChildren(list))
  return { children }
}

/** Sorted immediate children of a folder, or undefined when that folder does not exist. */
export function childrenOf(tree: Tree, source: Source, segments: string[]): Entry[] | undefined {
  return tree.children.get(key(source, segments.join('/')))
}

export function countChildren(children: Entry[]): { folders: number; files: number } {
  let folders = 0
  let files = 0
  for (const child of children) {
    if (child.kind === 'directory') folders += 1
    else files += 1
  }
  return { folders, files }
}

export function formatCounts({ folders, files }: { folders: number; files: number }): string {
  const plural = (count: number, noun: string) => `${count} ${noun}${count === 1 ? '' : 's'}`
  return `${plural(folders, 'folder')} · ${plural(files, 'file')}`
}
