import { useCallback, useEffect, useRef, useState, type MouseEvent } from 'react'

type ScrollState = { scrollY?: number } | null

function readPathname(): string {
  return window.location.pathname
}

function savedScroll(): number | null {
  const state = window.history.state as ScrollState
  return typeof state?.scrollY === 'number' ? state.scrollY : null
}

function rememberScroll() {
  const state = (window.history.state ?? {}) as Exclude<ScrollState, null>
  window.history.replaceState({ ...state, scrollY: window.scrollY }, '')
}

/**
 * Minimal history router: the pathname is the only routing state.
 * Entering a folder pushes a history entry and starts at the top; going back through history restores the
 * scroll position that was saved for that entry. Restoration is applied by the caller once the listing has
 * rendered (see restoreScroll), so it works even when data arrives after the navigation.
 */
export function useLocation() {
  const [pathname, setPathname] = useState(readPathname)
  const pendingScroll = useRef<number | null>(savedScroll())

  useEffect(() => {
    if ('scrollRestoration' in window.history) window.history.scrollRestoration = 'manual'
    const onPopState = () => {
      pendingScroll.current = savedScroll() ?? 0
      setPathname(readPathname())
    }
    let timer: number | undefined
    const onScroll = () => {
      window.clearTimeout(timer)
      timer = window.setTimeout(rememberScroll, 120)
    }
    window.addEventListener('popstate', onPopState)
    window.addEventListener('scroll', onScroll, { passive: true })
    return () => {
      window.removeEventListener('popstate', onPopState)
      window.removeEventListener('scroll', onScroll)
      window.clearTimeout(timer)
    }
  }, [])

  const navigate = useCallback((href: string) => {
    const target = new URL(href, window.location.href)
    if (target.pathname === window.location.pathname) return
    rememberScroll()
    window.history.pushState({ scrollY: 0 }, '', target.pathname)
    pendingScroll.current = 0
    setPathname(target.pathname)
  }, [])

  /** Applies any pending scroll restoration exactly once. Call after the destination content has rendered. */
  const restoreScroll = useCallback(() => {
    if (pendingScroll.current === null) return
    const top = pendingScroll.current
    pendingScroll.current = null
    window.scrollTo({ top, left: 0, behavior: 'instant' })
  }, [])

  return { pathname, navigate, restoreScroll }
}

/** True for plain left clicks that should be handled in-app; modified clicks keep the browser's default. */
export function isPlainNavigation(event: MouseEvent<HTMLAnchorElement>): boolean {
  return event.button === 0 && !event.metaKey && !event.ctrlKey && !event.shiftKey && !event.altKey && !event.defaultPrevented
}
